function validate(input) {
  const [{ logs = [] }] = input;
  const ids = new Set();
  for (const [id, ip] of logs) {
    if (id === null) return 'Every log needs a log_id.';
    if (ids.has(id)) return `log_id ${id} appears twice.`;
    ids.add(id);
    if (ip === null || !/^\d{1,3}(\.\d{1,3})*$/.test(ip)) return `ip ${ip} must be octets of 1 to 3 digits joined by dots.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const octet = () => {
    const r = rand();
    if (r < 0.7) return String(Math.floor(rand() * 256));
    if (r < 0.8) return '0';
    if (r < 0.9) return rand() < 0.5 ? '0' + Math.floor(rand() * 10) : '0' + String(Math.floor(rand() * 100)).padStart(2, '0');
    return String(256 + Math.floor(rand() * 744));
  };
  const address = () => {
    const r = rand(), count = r < 0.7 ? 4 : r < 0.8 ? 3 : r < 0.9 ? 5 : pick([1, 2, 6]);
    return Array.from({ length: count }, octet).join('.');
  };
  const fixed = ['192.168.1.1', '256.1.2.3', '192.168.001.1', '192.168.1', '0.0.0.0', '255.255.255.255', '1.2.3.4.5', '10.0.0.00', '9.9.9', '10.0.0'];
  const pool = Array.from({ length: size === 'small' ? 4 : 400 }, () => rand() < 0.4 ? pick(fixed) : address());
  const rows = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const logs = [];
  for (let i = 0; i < rows; i++) logs.push([i + 1, pick(pool), pick([200, 301, 404, 500])]);
  return [{ logs }];
}
